import "server-only";

/*
 * Municípios do Brasil (fonte: IBGE, servicodados.ibge.gov.br/api/v1/localidades). Gerado uma vez; não é lido em
 * tempo de execução de serviço nenhum. O "codigo" é o IBGE de 6 dígitos (o id de 7 do IBGE sem o dígito verificador),
 * que é o que a API do CNES espera no parâmetro ?municipio=. Usado só no seletor Estado -> Município da importação por CNES.
 * Fica no servidor (não vai inteiro para o navegador): a tela pede os municípios de um estado por vez.
 */

export interface MunicipioIbge {
  /** Código IBGE de 6 dígitos (o que o CNES usa). */
  codigo: string;
  nome: string;
}

