/** Municípios de um estado (sigla da UF), em ordem de nome. Vazio se a UF não existe. */
export function municipiosDoEstado(uf: string): MunicipioIbge[] {
  return MUNICIPIOS_POR_UF[uf] ?? [];
}

/** Nome do município pelo código IBGE de 6 dígitos (para mostrar na tela), ou "" se não achar. */
export function nomeDoMunicipio(codigo: string): string {
  for (const lista of Object.values(MUNICIPIOS_POR_UF)) {
    const m = lista.find((x) => x.codigo === codigo);
    if (m) return m.nome;
  }
  return "";
}
